// ============================================================
// VALIDATION DU LOT DE VOCALISATION
// ============================================================
// Jumeau du `Validate Input` de `Torah Batch Dispatcher`, et volontairement
// SÉPARÉ de lui : le contrat d'entrée n'est pas le même. La traduction exige
// `segmentText` et exactement UN de (commentary_id, segment_id) ; la
// vocalisation lit `text` et s'enregistre aussi par `source_text_id`. Fusionner
// les deux aurait mis un `if (tache === …)` dans les deux nœuds les plus
// délicats du chemin payant de la traduction.
const input = $input.first().json;
const body = input.body || input;

const items = Array.isArray(body.items) ? body.items : [];
const apiKey = body.api_key || body.provider_api_key || '';
// Défaut aligné sur le reste du parc (MODEL_ANTHROPIC).
const model = body.model || 'claude-haiku-4-5-20251001';
const projectId = body.project_id || '';
const context = body.context || {};
// Reprise de job : la façade a déjà créé le job et l'appelant le sonde. En créer
// un second ici le laisserait `pending` pour toujours.
const jobId = body.job_id || null;
const correlationId = body.correlation_id || null;
const clientMetadata = body.client_metadata || null;
const provider = body.provider || null;

// ⚠️ PLAFOND PAR ITEM. La vocalisation réécrit le texte ENTIER — chaque nekuda est
// un codepoint distinct — d'où un budget de ~2 jetons par caractère. Au-delà de
// 8 000 caractères, le budget dépasserait le plafond de 16 000 et la réponse
// serait TRONQUÉE : des nekudot manquantes en fin de texte, sans erreur. Le chemin
// synchrone, lui, découpe (`Découper Texte`, tranches de 2 500). On refuse donc
// franchement plutôt que de livrer du texte amputé.
const MAX_CAR_PAR_ITEM = 8000;
const SEUIL_LOT = 10;

const errors = [];
if (items.length === 0) errors.push('Le champ "items" (tableau non vide) est requis');
if (!apiKey) errors.push('Le champ "api_key" (Anthropic) est requis');
if (!projectId) errors.push('Le champ "project_id" est requis');

// ── Garde-fou de fournisseur ────────────────────────────────────────────────
// Ce workflow soumet à l'API Message Batches d'ANTHROPIC. Chez OpenAI, le lot
// exige un téléversement de fichier JSONL (multipart), impossible ici. La façade
// ne bascule déjà que sur `anthropic` : ce contrôle est la ceinture, pas la
// bretelle — il attrape les appels DIRECTS à /webhook/torah-vocalize-batch.
// Pas de deux-points dans le message — n8n ne garde que ce qui suit le dernier.
if (provider && String(provider).toLowerCase() !== 'anthropic') {
  errors.push('Le lot de vocalisation n\'est disponible que chez anthropic, pas chez '
    + String(provider).toLowerCase()
    + ' — passer par /webhook/torah-vocalization, qui bascule alors sur le chemin synchrone');
}
// Un modèle d'un autre fournisseur soumis à Anthropic fait échouer le LOT ENTIER,
// et l'erreur vient alors d'un workflow que l'appelant n'a jamais appelé.
if (model && !/^claude/i.test(String(model).trim())) {
  errors.push('Le champ "model" doit etre un modele Claude pour un lot Anthropic, pas '
    + String(model).trim());
}

items.forEach((it, i) => {
  const texte = it && it.text;
  if (!texte || String(texte).trim().length === 0) {
    errors.push('items[' + i + '].text est requis');
  } else if (String(texte).length > MAX_CAR_PAR_ITEM) {
    errors.push('items[' + i + '].text fait ' + String(texte).length
      + ' caracteres, au-dela du plafond de ' + MAX_CAR_PAR_ITEM
      + ' que le lot sait traiter sans troncature — passer cet item par le chemin synchrone, qui decoupe');
  }
  // Au moins UN identifiant, sinon le résultat n'est rattachable à rien et le
  // callback ne pourrait que le jeter — après l'avoir payé.
  if (!it || (!it.commentary_id && !it.source_text_id && !it.segment_id)) {
    errors.push('items[' + i + '] : commentary_id, source_text_id ou segment_id requis');
  }
});

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    items: items,
    api_key: apiKey,
    model: model,
    project_id: projectId,
    context: context,
    seuil_lot: SEUIL_LOT,
    job_type: body.job_type || 'torah_vocalization',
    // Omis plutôt que posés à null, comme dans le dispatcher de traduction : la
    // sortie reste identique au caractère près pour un appelant qui n'en fournit pas.
    ...(jobId ? { job_id: jobId } : {}),
    ...(correlationId ? { correlation_id: correlationId } : {}),
    ...(correlationId || clientMetadata ? { client_metadata: clientMetadata } : {}),
    provider: provider
  }
}];

// ============================================================
// CONSTRUCTION DES REQUÊTES DU LOT — vocalisation
// ============================================================
const body = $('Validate Input').first().json;
const jobId = $('Résoudre Job').first().json.job_id;
const model = body.model;

// ⚠️⚠️ L'INVITE EST REPRISE MOT POUR MOT DE `Vocaliser (LLM)` DU CHEMIN SYNCHRONE.
// Ce n'est pas de la duplication paresseuse : le lot vocalise avec un modèle
// Claude là où le défaut synchrone est `gpt-4o`, et la pose des nekudot est
// exactement l'endroit où un changement de modèle se voit. Garder l'invite
// identique est le seul moyen de limiter l'écart à ce qui vient du modèle.
// Toute retouche ici DOIT être reportée là-bas, et inversement.
const SYSTEME = 'Tu es un expert en hébreu biblique et rabbinique. Ta tâche est d\'ajouter les nekudot (voyelles hébraïques/signes de vocalisation) au texte hébreu fourni. Retourne UNIQUEMENT le texte vocalisé, sans explication ni commentaire.';
const consigne = (texte) => 'Ajoute les nekudot (voyelles hébraïques) à ce texte:\n\n' + texte;

// Budget : même formule que le chemin synchrone — ~2 jetons par caractère, la
// vocalisation réécrivant tout. AUCUNE marge de raisonnement ici : les modèles
// Claude ne raisonnent pas par défaut, et `Validate Input` refuse un modèle non
// Claude. Si un jour un fragment `thinking` arrive, il faudra la provisionner
// (azy.daily#706).
const budget = (texte) => Math.min(16000, Math.max(1024, Math.ceil(String(texte).length * 2)));

// custom_id : l'identifiant de l'item, quel qu'il soit. Le prendre sur
// commentary_id seul donnerait « null » à tout item qui n'en a pas, et Anthropic
// refuse alors le LOT ENTIER (« custom_id`s must be unique within a batch »).
const refDe = (it) => it.commentary_id || it.source_text_id || it.segment_id;

const requests = body.items.map((it) => ({
  custom_id: String(refDe(it)),
  params: {
    model: model,
    max_tokens: budget(it.text),
    system: SYSTEME,
    messages: [{ role: 'user', content: consigne(it.text) }]
  }
}));

// Carte custom_id -> quoi sauvegarder. Le callback y retrouve la NATURE de l'item :
// un commentaire s'enregistre par commentary_id, un texte source par
// source_text_id, un verset par segment_id. Un seul des trois, jamais plusieurs —
// `/api/vocalization/save` refuse l'ambiguïté.
const carte_items = {};
body.items.forEach((it) => {
  const ref = String(refDe(it));
  carte_items[ref] = it.commentary_id ? { commentary_id: it.commentary_id }
    : it.source_text_id ? { source_text_id: it.source_text_id }
    : { segment_id: it.segment_id };
  // Le texte d'origine voyage avec : le callback doit pouvoir rendre
  // { original, vocalized } sans relire la base.
  carte_items[ref].original = it.text;
});

// L'appairage n'est ajouté que s'il a été demandé, pour que le metadata du lot
// reste identique au caractère près pour tout appelant qui ne le demande pas.
// correlation_id est posé AU PREMIER NIVEAU parce que `Claude - Call With Skills`
// le lit là : sans lui, il en génère un que l'appelant ne peut pas reconnaître.
const appairage = body.correlation_id ? { correlation_id: body.correlation_id } : {};
const appairageMeta = body.correlation_id
  ? { correlation_id: body.correlation_id, client_metadata: body.client_metadata || {} }
  : {};

return {
  ...appairage,
  api_key: body.api_key,
  callback_url: $env.N8N_WEBHOOK_URL + '/webhook/torah-vocalization-callback',
  metadata: {
    multi: true,
    tache: 'vocalisation',
    job_id: jobId,
    project_id: body.project_id,
    provider: 'anthropic',
    model: model,
    traite: body.context && body.context.traite,
    page: body.context && body.context.page,
    carte_items: carte_items,
    ...appairageMeta
  },
  requests
};

// Construire la réponse d'erreur de validation
const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];

// Le job_id, qu'il vienne de l'appelant ou de notre propre Create Job.
//
// Ce nœud existe parce qu'on ne peut PAS écrire $('Create Job') en aval : sur la
// branche « job fourni » ce nœud n'a pas tourné, et n8n lève « Referenced node is
// unexecuted ». Tout ce qui suit lit donc $('Résoudre Job') à la place.
//
// Deux formes d'entrée :
//   branche fournie  → l'item vient de Validate Input et porte déjà job_id
//   branche créée    → $json porte la réponse de POST /api/v2/jobs
const valide = $('Validate Input').first().json;
const recu = $input.first().json || {};
const fourni = valide.job_id || null;
const jobId = fourni || recu.job_id || recu.id || null;

// On renvoie le payload VALIDÉ, pas la réponse de l'API : Build Requests lit
// déjà $('Validate Input'), et les nœuds suivants ont besoin de project_id.
return [{ json: { ...valide, job_id: jobId, job_cree_ici: !fourni } }];

// Le job doit exister AVANT de soumettre : sans lui, le lot part chez Anthropic
// et devient introuvable — travail lancé, facturé, intraçable.
// Create Job est en continueErrorOutput ET peut ne pas avoir tourné du tout
// (reprise d'un job fourni) : c'est Résoudre Job qui porte l'identifiant dans les
// deux cas. On vérifie quand même, parce qu'un id absent produirait une réponse
// d'apparence normale : JSON.stringify omet silencieusement les undefined.
const jobId = $('Résoudre Job').first().json.job_id || null;
// $('Submit'), pas $input : depuis l'insertion de Set Processing entre les deux,
// $json porte la réponse du PATCH de statut — batch_id, redis_channel et
// correlation_id y sont absents, et le lot redevenait introuvable alors même
// qu'il tournait. Un nœud inséré déplace la source de tout ce qui le suit.
const soumission = $('Submit').first().json || {};
const count = $('Build Requests').first().json.requests.length;

if (!jobId) {
  return [{ json: {
    success: false,
    batch: true,
    count: count,
    batch_id: soumission.batch_id || null,
    error: {
      code: 502,
      message: 'Lot soumis mais job non créé : le suivi est impossible. Conserver le batch_id.',
      status: 'JOB_CREATION_FAILED'
    }
  } }];
}

return [{
  json: {
    success: true,
    job_id: jobId,
    batch: true,
    count: count,
    // Remontés pour que le lot reste retrouvable même si le suivi par job casse.
    batch_id: soumission.batch_id || null,
    redis_channel: soumission.redis_channel || null,
    correlation_id: soumission.correlation_id || null
  }
}];

// Le lot n'est pas parti : le job vient d'être marqué failed, et l'appelant
// doit le savoir tout de suite plutôt que de poller un job qui n'avancera
// jamais. Sans cette branche, Set Processing s'exécutait quand même et le
// job affichait « processing » alors que rien n'avait été soumis.
const e = $('Submit').first().json || {};
const brut = String(e?.error?.message || e?.message || '');
return [{ json: {
  success: false,
  job_id: $('Résoudre Job').first().json.job_id || null,
  batch: true,
  error: {
    code: 502,
    message: 'Soumission du lot impossible — aucune requête envoyée, job marqué failed. ' + brut.slice(0, 200),
    status: 'BATCH_SUBMIT_FAILED'
  }
} }];

// Création du job impossible : on n'a pas soumis le lot, donc rien n'est engagé.
// Refuser franchement vaut mieux que dépenser sans pouvoir suivre.
const e = $input.first().json || {};
const brut = String(e?.error?.message || e?.message || '');
return [{ json: {
  success: false,
  error: {
    code: 502,
    message: 'Création du job impossible — lot NON soumis, aucun coût engagé. ' + brut.slice(0, 200),
    status: 'JOB_CREATION_FAILED'
  }
} }];
